# [LATER-STEP] result_translate.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef translate(text: str, target_lang: str = \"en\") -> str:\n    \"\"\"Translate the given text to the target language using the configured translation provider.\"\"\"\n    provider = os.getenv(\"PROVIDER\", \"alibaba\").lower()\n    if provider == \"alibaba\":\n        from alibabacloud_alimt20181011.client import Client as AliMtClient\n        from alibabacloud_tea_util.models import RuntimeOptions\n        # Assuming credentials are set via environment variables:\n        # ALIBABA_CLOUD_ACCESS_KEY_ID and ALIBABA_CLOUD_ACCESS_KEY_SECRET\n        client = AliMtClient(\n            access_key_id=os.getenv(\"ALIBABA_CLOUD_ACCESS_KEY_ID\"),\n            access_key_secret=os.getenv(\"ALIBABA_CLOUD_ACCESS_KEY_SECRET\"),\n        )\n        request = client.translate_text(\n            SourceLanguage=\"auto\",\n            TargetLanguage=target_lang,\n            SourceText=text,\n        )\n        return request.get(\"TranslatedText\")\n    elif provider == \"deepl\":\n        import deepl\n        translator = deepl.Translator(os.getenv(\"DEEPL_AUTH_KEY\"))\n        result = translator.translate_text(text, target_lang=target_lang)\n        return result[\"text\"]\n    elif provider == \"google\":\n        from google.cloud import translate_v2 as translate\n        client = translate.Client()\n        result = client.translate(text, target_language=target_lang)\n        return result[\"translatedText\"]\n    elif provider == \"azure\":\n        from azure.ai.translation import TextTranslationClient\n        from azure.core.credentials import AzureKeyCredential\n        client = TextTranslationClient(\n            endpoint=os.getenv(\"AZURE_TRANSLATOR_ENDPOINT\"),\n            credential=AzureKeyCredential(os.getenv(\"AZURE_TRANSLATOR_KEY\")),\n        )\n        result = client.translate(\n            text=text, target_language=target_lang,\n        )\n        return result[0][\"translations\"]\n    elif provider == \"amazon\":\n        import boto3\n        client = boto3.client(\"translate\")\n        result = client.translate_text(Text=text, TerminologyNames=[], SourceLanguageCode=\"auto\", TargetLanguageCode=target_lang)\n        return result[\"TranslatedText\"]\n    else:\n        # Default fallback – return original text\n        return text\n